function detectLang(){
  const nav=(navigator.language||navigator.userLanguage||"pt").toLowerCase();
  if(nav.startsWith("es")) return "es";
  if(nav.startsWith("pt")) return "pt";
  if(nav.startsWith("en")) return "en";
  return "pt";
}

