      S.current.movedEnough=false;S.current.dragging=isPan?null:(hit||null);
      S.current.panning=false;S.current.downPan={panX:S.current.panX,panY:S.current.panY};
      S.current.magPos=isPan?null:{ix:imgPt.x,iy:imgPt.y};
